from collections import deque

def merge(x, y):
	if len(x) > len(y):
		(x, y) = (y, x)
	for i in x:
		y[i] = y[i] + x[i] if i in y else x[i]
	return (y, y)

def NC_Dij(lis, start):
	ret = [float('inf')] * len(lis)
	ret[start] = 0
	q = deque([start])
	plis = [i for i in range(len(lis))]
	while len(q) > 0:
		now = q.popleft()
		for nex in lis[now]:
			if ret[nex] > ret[now] + 1:
				ret[nex] = ret[now] + 1
				plis[nex] = now
				q.append(nex)
	return (ret, plis)
mod = 10 ** 9 + 7
for loop in range(int(input())):
	N = int(input())
	lis = [[] for i in range(N)]
	for i in range(N - 1):
		(u, v) = map(int, input().split())
		u -= 1
		v -= 1
		lis[u].append(v)
		lis[v].append(u)
	(dlis, P) = NC_Dij(lis, 0)
	chnum = [0] * N
	for i in range(1, N):
		chnum[P[i]] += 1
	a = list(map(int, input().split()))
	cds = [{} for i in range(N)]
	allsum = [0] * N
	q = deque([])
	leaf = [False] * N
	ans = 0
	for i in range(N):
		if chnum[i] == 0:
			q.append(i)
			leaf[i] = True
	while q:
		v = q.popleft()
		nans = allsum[v] if a[v] not in cds[v] else allsum[v] - cds[v][a[v]]
		if leaf[v]:
			nans = 1
		nans %= mod
		ans += nans
		ans %= mod
		if a[v] not in cds[v]:
			cds[v][a[v]] = 0
		cds[v][a[v]] += nans
		cds[v][a[v]] %= mod
		if P[v] != v:
			chnum[P[v]] -= 1
			(cds[P[v]], cds[v]) = merge(cds[P[v]], cds[v])
			allsum[P[v]] = (allsum[P[v]] + allsum[v] + nans) % mod
			if chnum[P[v]] == 0:
